body:
I can confirm this occurs in Godot 4.6.3.

Here's the script I used for testing. Attach it to some visible object within your scene, give it a reference to the camera, and use inspector buttons to control it in editor or arrows to control it in game.

<details> 
      <summary>Code</summary>

    @tool
    extends Node3D

    @export var camera: Camera3D;

    @export_tool_button("right") var right_button = go_right
    @export_tool_button("left") var left_button = go_left
    @export_tool_button("up") var up_button = go_up
    @export_tool_button("down") var down_button = go_down

    func _process(delta: float) -> void:
    	if not Engine.is_editor_hint():
    		if Input.is_action_pressed("ul_right"):
    			go_right()
    		elif Input.is_action_pressed("ui_left"):
    			go_left()
    		elif Input.is_action_pressed("ui_up"):
    			go_up()
    		elif Input.is_action_pressed("ui_down"):
    			go_down()

    func go_right():
    	var size = get_viewport().size
    	position = camera.project_position(Vector2(size.x, 0.5  * size.y), 2)
    	print(camera.unproject_position(global_position))

    func go_left():
    	var size = get_viewport().size
    	position = camera.project_position(Vector2(0, 0.5  * size.y), 2)
    	print(camera.unproject_position(global_position))

    func go_up():
    	var size = get_viewport().size
    	position = camera.project_position(Vector2(0.5 * size.x, 0), 2)
    	print(camera.unproject_position(global_position))

    func go_down():
    	var size = get_viewport().size
    	position = camera.project_position(Vector2(0.5 * size.x, size.y), 2)
    	print(camera.unproject_position(global_position))
</details>

Not only are the numbers of the coordinate system different than you'd get from running the game (annoying but understandable), the projection matrix doesn't seem to take the camera's aspect ratio into account (much more difficult to work around). Moving to the "leftmost" side of the screen puts the object 3/4 of the way over instead.

